#!/usr/bin/env bash
unset CLAUDECODE
exec claude --no-chrome --permission-mode dontAsk --allowedTools Bash,Read,TaskStop,KillShell --model haiku --effort low --setting-sources '' --strict-mcp-config --mcp-config '{"mcpServers":{}}' --system-prompt 'You are driving a disposable background-task evaluation. Follow only the user instructions for the fixture. Do not supervise any fleet, launch agents, or read unrelated files. All files and commands you create must be under the provided fixture directory. Do not use /stow; this fixture has no open work records to persist. When receiving a Firstmate inbox doorbell, use Bash to read the .msg files in the named inbox, carry out their cleanup instructions, and publish a correlated done reply using the provided status-append script, then move each message into handled/.' "$FM_EVAL_PROMPT"
